const navItems=[['home','Inicio'],['map','Mapa'],['compose','Crear'],['messages','Mensajes'],['profile','Perfil']];
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function showToast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toastEl.classList.remove('show'),2400)}
function business(name){return businesses.find(b=>b.name===name)||businesses[0]}
function setPage(page){state.page=page;state.chat=null;render()}
function openBusiness(name){state.selectedBusiness=name;state.page='business';render()}
function navGlyph(id){const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15m6-12v15"/>',messages:'<path d="M4 5.5A3.5 3.5 0 0 1 7.5 2h9A3.5 3.5 0 0 1 20 5.5v8a3.5 3.5 0 0 1-3.5 3.5H10l-5 4v-5.2A3.5 3.5 0 0 1 4 13.5z"/><path d="M8 8h8m-8 4h6"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'};return `<svg class="nav-svg" viewBox="0 0 24 24" aria-hidden="true">${paths[id]||''}</svg>`}
function navRender(){if(state.page==='onboarding'){nav.innerHTML='';return}const owner=state.page.startsWith('merchant-');if(owner){const items=[['merchant-dashboard','⌂','Inicio'],['merchant-products','▣','Productos'],['merchant-orders','▤','Pedidos'],['merchant-analytics','▥','Ventas'],['merchant-more','···','Más']];nav.innerHTML=items.map(([id,icon,label])=>`<button class="nav-item ${state.page===id||state.page==='merchant-product-form'&&id==='merchant-products'||state.page==='merchant-order-detail'&&id==='merchant-orders'?'active':''}" data-owner-page="${id}"><span class="owner-nav-icon">${icon}</span><span>${label}</span></button>`).join('');return}nav.innerHTML=navItems.map(([id,label])=>`<button class="nav-item ${state.page===id||state.page==='business'&&id==='map'||state.page==='chat'&&id==='messages'||state.page==='marketing'&&id==='profile'||['shop-discover','storefront','product-detail','cart','checkout','payment-processing','order-confirmation','my-orders','customer-order-detail'].includes(state.page)&&id==='home'?'active':''}" data-page="${id}" aria-label="${label}">${id==='compose'?`<span class="nav-create">＋</span>`:`${navGlyph(id)}${id==='messages'?'<span class="nav-badge">3</span>':''}`}<span>${label}</span></button>`).join('')}
function header(title,sub='',action=''){return `<div class="page-header"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function searchBox(value,placeholder,action='search-change',klass=''){return `<label class="search ${klass}"><span>⌕</span><input data-action="${action}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${placeholder}" /></label>`}
function photoClass(b){return {'Café Nopal':'photo-cafe','Florería El Jardín':'photo-florist','Taller Luna':'photo-workshop','Panadería La Espiga':'photo-feed'}[b.name]||'photo-cafe'}
function artCard(b){return `<article class="business-card" data-open-business="${esc(b.name)}"><div class="business-art ${b.art} ${photoClass(b)}"><span class="art-emoji">${b.emoji}</span></div><div class="business-info"><strong>${b.name}</strong><small>${b.type}</small><div class="business-loc">⌖ ${b.zone}<span style="margin-left:auto;color:#258a41;font-size:17px">＋</span></div></div></article>`}
function avatar(emoji,extra=''){return `<div class="avatar ${extra}">${emoji}</div>`}
function postCard(post){return `<article class="post-card"><div class="post-author">${avatar(post.emoji||'☕')}<div><strong>${esc(post.name)}</strong><small>${esc(post.meta||'Hace 2 horas · Roma Norte')}</small></div><button class="more" data-toast="Más opciones próximamente">···</button></div><div class="post-text">${esc(post.text)}</div>${post.image?`<div class="post-image ${post.photo?'photo-feed':''}">${post.photo?'':`<span>${post.image}</span>`}</div>`:''}<div class="post-actions"><button class="post-action" data-toast="Te gusta esta publicación">♡ Me gusta</button><button class="post-action" data-toast="Comentarios próximamente">◯ Comentar</button><button class="post-action" data-toast="Enlace copiado">↗ Compartir</button></div></article>`}
const defaultPosts=[{name:'Café Nopal',emoji:'🌵',meta:'Hace 2 horas · Roma Norte',text:'¡Ya tenemos pan de muerto! 😍☕ Este fin de semana ven a probar nuestra nueva receta artesanal.',image:'☕ 🥐',photo:true},{name:'Florería El Jardín',emoji:'🌷',meta:'Hace 5 horas · Condesa',text:'Llegaron flores de temporada de productores locales 🌼 Pásenle a conocerlas.'}];
function home(){let q=state.query.trim().toLowerCase();let near=businesses.filter(b=>!q||`${b.name} ${b.type} ${b.zone}`.toLowerCase().includes(q));let posts=[...state.posts,...defaultPosts];if(q)posts=posts.filter(p=>`${p.name} ${p.text}`.toLowerCase().includes(q));return `<section class="page home-page"><div class="home-brand"><div><div class="mini-brand">BARRIO</div><div class="mini-tag">Comercio que conecta</div></div></div><div class="home-head"><div class="home-greeting"><h1>Hola, Ana 👋</h1><p>Descubre, conéctate y haz crecer<br>tu negocio en tu barrio.</p></div><div class="home-actions"><button class="icon-button notification-button" data-toast="No tienes notificaciones nuevas" aria-label="Notificaciones"><span>♧</span><i class="notification-dot"></i></button>${avatar('👩🏻','user-avatar')}</div><span class="welcome-leaves" aria-hidden="true">🌿</span></div><div class="search-row">${searchBox(state.query,'Buscar comercios o personas')}<button class="icon-button" data-toast="Filtros de búsqueda próximamente" aria-label="Filtros">☷</button></div><div class="home-flow-shortcuts"><button data-page="shop-discover"><span>🛍️</span><b>Comprar local</b></button><button data-page="merchant-dashboard"><span>🏪</span><b>Mi negocio</b></button></div><div class="section-heading"><h2>Comercios cerca de ti</h2><button class="text-button" data-page="map">Ver todos ›</button></div><div class="business-row">${near.length?near.slice(0,6).map(artCard).join(''):'<div class="empty-state">No encontramos comercios.</div>'}</div><div class="section-heading"><h2>Publicaciones de tu comunidad</h2><button class="text-button" data-page="compose">Compartir＋</button></div>${posts.length?posts.map(postCard).join(''):'<div class="empty-state">No hay publicaciones que coincidan con tu búsqueda.</div>'}</section>`}
const mapPins=[{n:'Café Nopal',x:20,y:26,e:'☕',c:''},{n:'Florería El Jardín',x:69,y:36,e:'🌷',c:'pink'},{n:'Taller Luna',x:49,y:50,e:'🔧',c:'blue'},{n:'Panadería La Espiga',x:34,y:68,e:'🥐',c:'gold'},{n:'Mercado de Coyoacán',x:74,y:76,e:'🏪',c:'green'}];
function mapSvg(){return `<svg class="map-drawing" viewBox="0 0 360 470" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="dots" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="3" cy="4" r="1.3" fill="#8cc47d" opacity=".55"/></pattern></defs><rect width="360" height="470" fill="#b7e9a3"/><rect width="360" height="470" fill="url(#dots)"/><path d="M-10 70 Q45 40 100 80T205 65T370 100M-15 145 Q55 115 115 150T240 132T375 168M-15 240 Q60 212 130 245T265 225T375 256M-10 330 Q60 300 130 338T260 318T380 350M-10 412 Q55 380 120 416T250 395T380 430" fill="none" stroke="#f9efbd" stroke-width="9"/><path d="M60 -10 Q85 50 70 110T95 220T76 350T90 490M175 -10 Q150 60 180 120T165 240T195 330T170 490M290 -10 Q265 60 300 140T275 250T305 360T290 490" fill="none" stroke="#f9efbd" stroke-width="8"/><path d="M8 115 Q44 86 70 110L68 146 25 160ZM230 48 Q270 30 314 62L302 94 252 88ZM36 276 L84 260 105 300 70 323ZM210 190L260 181 281 218 230 236ZM119 370L165 350 185 388 144 410Z" fill="#78be6d" stroke="#589c58" stroke-width="2"/><path d="M18 386 Q62 368 100 386T181 380T260 391T370 375L370 470H0Z" fill="#70c9d5" opacity=".9"/><path d="M20 100 Q50 92 75 106L95 130M94 215 Q139 198 173 217T247 211M166 131 Q214 110 261 130T322 151M58 315 Q104 300 142 320T232 312" fill="none" stroke="#d5a76a" stroke-width="3" stroke-dasharray="4 5"/><g fill="#f8f1ce" stroke="#966b44" stroke-width="2"><path d="M143 78h26v30h-26zM139 78l17-17 17 17z"/><path d="M271 246h31v25h-31zM267 246l20-17 20 17z"/><path d="M103 180h25v27h-25zM99 180l16-15 17 15z"/><path d="M217 346h30v26h-30zM214 346l18-15 18 15z"/></g><g fill="#3f8c4a"><circle cx="33" cy="191" r="8"/><circle cx="42" cy="194" r="8"/><circle cx="55" cy="61" r="9"/><circle cx="63" cy="66" r="9"/><circle cx="329" cy="189" r="8"/><circle cx="337" cy="194" r="8"/><circle cx="192" cy="285" r="8"/><circle cx="201" cy="288" r="8"/><circle cx="122" cy="435" r="8"/><circle cx="132" cy="438" r="8"/></g><g fill="#fff" font-family="sans-serif" font-weight="800" font-size="10"><text x="140" y="126">ZÓCALO</text><text x="95" y="237">ROMA</text><text x="270" y="293">DEL VALLE</text><text x="206" y="387">COYOACÁN</text></g></svg>`}
function mapPage(){
 let q=state.mapQuery.toLowerCase();
 let shown=mapPins.filter(p=>(state.mapFilter==='Todos'||business(p.n).kind===state.mapFilter)&&(!q||p.n.toLowerCase().includes(q)||business(p.n).zone.toLowerCase().includes(q)));
 let b=business(state.selectedBusiness);
 return `<div class="map-screen"><div class="map-head"><div class="map-title"><span class="pin-big">📍</span><div><h1>Comercios cerca de ti</h1><p>Explora negocios en tu zona y conéctate.</p></div></div><div class="search-row map-search">${searchBox(state.mapQuery,'Buscar en esta zona','map-search-change')}<button class="icon-button" data-toast="Elige un giro para filtrar el mapa" aria-label="Filtros">☷</button></div><div class="chips">${['Cafés','Tiendas','Servicios','Todos'].map(k=>`<button class="chip ${state.mapFilter===k?'selected':''}" data-filter="${k}">${{Todos:'🛒',Cafés:'☕',Tiendas:'▣',Servicios:'🔧'}[k]} ${k}</button>`).join('')}</div></div><div class="map-canvas" role="region" aria-label="Mapa ilustrado de comercios en Ciudad de México">${[['Centro',43,14],['Roma Norte',13,39],['Del Valle',55,58],['Coyoacán',28,79],['Xochimilco',65,88]].map(([t,x,y])=>`<span class="map-label" style="left:${x}%;top:${y}%">${t}</span>`).join('')}${shown.map(p=>`<button class="map-marker ${p.c} ${state.selectedBusiness===p.n&&state.mapDetailOpen?'selected':''}" style="left:${p.x}%;top:${p.y}%" data-marker="${esc(p.n)}" aria-label="${esc(p.n)}"><span>${p.e}</span></button>`).join('')}<div class="map-controls"><button data-toast="Centrando mapa en tu zona" aria-label="Centrar mapa">◎</button><button data-toast="Acercamiento de mapa" aria-label="Acercar">⌖</button></div><div class="map-legend"><div class="legend-item"><i class="legend-dot"></i>Cafeterías</div><div class="legend-item">🔧 Servicios</div><div class="legend-item">🛍️ Tiendas</div><div class="legend-item">🌷 Salud y belleza</div></div>${state.mapDetailOpen&&shown.length?`<div class="map-selected" data-open-business="${esc(b.name)}"><span class="selected-emoji">${b.emoji}</span><strong>${b.name}</strong><small>${b.type} · ${b.zone}</small></div>`:''}</div></div>`
}
function businessPage(){let b=business(state.selectedBusiness);return `<section class="page"><div class="profile-cover"><button class="cover-back" data-page="map">‹</button><span class="cover-name">${esc(b.name.toUpperCase())}</span></div><div class="profile-sheet"><div class="profile-overview"><div class="profile-logo">${b.name==='Café Nopal'?'🌵':b.emoji}</div><div class="profile-title"><h1>${b.name} <span class="verified">●</span></h1><p>${b.type} · ${b.zone}</p></div></div><div class="profile-stats"><div class="stat"><strong>${b.followers}</strong><small>seguidores</small></div><div class="stat"><strong>124</strong><small>siguiendo</small></div><div class="stat"><strong>${b.posts}</strong><small>publicaciones</small></div></div><div class="profile-buttons"><button class="primary-button" data-connect>${state.connected?'✓ Conectado':'♧ Conectar'}</button><button class="secondary-button" data-chat="${esc(b.name)}">▢ Mensaje</button></div><p class="bio">${b.about}</p><div class="open-line">◷ <b>Abierto</b> · Cierra a las 21:00 <span>⌄</span></div><div class="tabs">${['Publicaciones','Información','Opiniones'].map(t=>`<button class="tab ${state.businessTab===t?'selected':''}" data-business-tab="${t}">${t}</button>`).join('')}</div>${state.businessTab==='Publicaciones'?postCard({name:b.name,emoji:b.emoji,meta:'Hace 3 días',text:'Nuevo en el menú: latte de mazapán. ¡Ven a probarlo! ☕✨',image:'☕',photo:true}):state.businessTab==='Información'?`<div class="detail-grid"><div class="detail-cell"><b>UBICACIÓN</b>${b.zone}, CDMX</div><div class="detail-cell"><b>HORARIO</b>Lun a dom · 8:00–21:00</div><div class="detail-cell"><b>GIRO</b>${b.type}</div><div class="detail-cell"><b>ACEPTA</b>Efectivo y tarjeta</div></div><p class="bio">${b.about}</p>`:`<div class="empty-state">Aún no hay opiniones. ¡Sé el primero en compartir tu experiencia!</div>`}</div></section>`}
function messagesPage(){let q=state.messageQuery.toLowerCase();let list=conversations.filter(c=>(state.messageFilter==='Todos'||c.kind===state.messageFilter)&&(!q||c.name.toLowerCase().includes(q)||c.preview.toLowerCase().includes(q)));return `<section class="page">${header('Mensajes','Conversa con otros comercios','<button class="icon-button" data-toast="Nueva conversación: selecciona un comercio">✎</button>')}${searchBox(state.messageQuery,'Buscar conversaciones','message-search-change','message-search')}<div class="segmented">${['Todos','Comercios','Grupos'].map(k=>`<button class="segment ${state.messageFilter===k?'selected':''}" data-message-filter="${k}">${k==='Comercios'?'♧ ':k==='Grupos'?'♙ ':''}${k}</button>`).join('')}</div>${list.length?list.map(c=>`<button class="conversation" data-chat="${esc(c.name)}">${avatar(c.emoji)}<span class="conversation-copy"><strong>${c.name}</strong><p>${esc(c.preview)}</p></span><span class="conversation-time">${c.time}${c.unread?`<i class="unread">${c.unread}</i>`:''}</span></button>`).join(''):'<div class="empty-state">No hay conversaciones que coincidan.</div>'}</section>`}
function composePage(){return `<section class="page"><div class="back-row"><button data-page="home">‹</button><span style="font:800 12px Nunito,sans-serif">Nueva publicación</span></div><div style="text-align:center;margin:8px 0 16px"><h1 style="font:900 20px Nunito,sans-serif;margin:0">Comparte con tu comunidad</h1><p style="margin:4px 0;color:var(--muted);font-size:11px">Cuéntanos qué está pasando en tu negocio.</p></div><div class="compose-types">${[['Novedad','📣','Comparte una actualización'],['Pregunta','❔','Pide consejos a la comunidad'],['Recomendación','⭐','Sugiere un negocio o servicio']].map(([t,e,d])=>`<button class="compose-type ${state.postType===t?'selected':''}" data-post-type="${t}"><span>${e}</span><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><textarea class="compose-box" maxlength="500" placeholder="Escribe tu publicación aquí..." data-compose-text>${esc(state.composeText)}</textarea><div class="char-count"><span id="charcount">${state.composeText.length}</span>/500</div><div class="compose-tools">${[['Fotos','▧'],['Ubicación','♧'],['Etiquetar negocio','▣']].map(([t,e])=>`<button class="tool-button ${state.tools[t]?'selected':''}" data-tool="${t}"><span>${e}</span>${state.tools[t]?'✓ ':''}${t}</button>`).join('')}</div><div class="audience-title">¿Quién puede ver esta publicación?</div><button class="audience-select" data-audience><span>♧</span><span>${state.audience}</span><span>›</span></button><button class="publish-button" data-publish>➤ &nbsp;Publicar</button></section>`}
function profilePage(){return `<section class="page">${header('Mi perfil','Tu espacio en BARRIO','<button class="icon-button" data-toast="Editar perfil próximamente">⚙</button>')}<div class="profile-person">${avatar('👩🏻','user-avatar')}<div><h2>Ana Torres</h2><p>Comerciante · Roma Norte, CDMX</p><p style="color:#248544;font-weight:700">● Perfil completo</p></div></div><div class="profile-stats" style="background:#fff;border:1px solid var(--line);border-radius:14px;padding:12px"><div class="stat"><strong>82</strong><small>conexiones</small></div><div class="stat"><strong>14</strong><small>publicaciones</small></div><div class="stat"><strong>6</strong><small>grupos</small></div></div><div class="section-heading"><h2>Mi negocio</h2><button class="text-button" data-toast="Editar negocio próximamente">Editar</button></div><div class="profile-person" style="cursor:pointer" data-open-business="Café Nopal">${avatar('🌵')}<div><h2 style="font-size:14px">Café Nopal</h2><p>Cafetería · Roma Norte</p></div><span style="margin-left:auto;color:#879087">›</span></div><button class="marketing-entry" data-page="marketing"><span class="marketing-entry-icon">✦</span><span><strong>Impulsa tu negocio</strong><small>Crea una campaña para atraer clientes de tu zona.</small></span><b>›</b></button><div class="section-heading"><h2>Explora BARRIO</h2></div><div class="profile-flow-links"><button class="menu-row" data-page="onboarding"><span>✦</span>Primeros pasos y perfil<span class="arrow">›</span></button><button class="menu-row" data-page="shop-discover"><span>🛍️</span>Explorar productos locales<span class="arrow">›</span></button><button class="menu-row" data-page="merchant-dashboard"><span>▥</span>Herramientas para comerciantes<span class="arrow">›</span></button><button class="menu-row" data-page="my-orders"><span>📦</span>Mis pedidos<span class="arrow">›</span></button></div><div class="section-heading"><h2>Cuenta</h2></div><div class="menu-list">${[['♙','Información personal'],['♧','Mis conexiones'],['♧','Mis grupos'],['?','Ayuda y soporte']].map(([i,t])=>`<button class="menu-row" data-toast="${t} próximamente"><span>${i}</span>${t}<span class="arrow">›</span></button>`).join('')}</div></section>`}
const marketingObjectives=[['Atraer clientes','Que más personas de tu zona conozcan tu negocio.','📍'],['Anunciar un producto','Presenta algo nuevo o de temporada.','🛍️'],['Promover una oferta','Comparte una promoción especial.','🏷️'],['Invitar a volver','Saluda a quienes ya te conocen.','💚']];
function marketingProgress(){return `<div class="marketing-progress" aria-label="Paso ${state.marketingStep+1} de 4"><div class="marketing-progress-fill" style="width:${(state.marketingStep+1)*25}%"></div></div><div class="marketing-step-label">Paso ${state.marketingStep+1} de 4</div>`}
function marketingPage(){let step=state.marketingStep;let objective=marketingObjectives.find(o=>o[0]===state.marketingObjective);let copy=state.marketingCopy||`¡${state.marketingProduct||'Tenemos algo especial'} en Café Nopal! Ven a visitarnos en Roma Norte. Nos encanta recibir a nuestros vecinos de BARRIO. ☕`;
 if(step===0)return `<section class="page marketing-page"><div class="back-row"><button data-page="profile" aria-label="Volver al perfil">‹</button><span>Impulsa tu negocio</span></div>${marketingProgress()}<div class="marketing-intro"><span class="marketing-spark">✦</span><h1>¿Qué te gustaría lograr?</h1><p>Elige una meta para preparar una campaña que haga sentido para tu negocio. No necesitas experiencia en marketing.</p></div><div class="marketing-choice-list">${marketingObjectives.map(([title,desc,icon])=>`<button class="marketing-choice ${state.marketingObjective===title?'selected':''}" data-marketing-objective="${title}" aria-pressed="${state.marketingObjective===title}"><span class="marketing-choice-icon">${icon}</span><span><strong>${title}</strong><small>${desc}</small></span><i>${state.marketingObjective===title?'✓':'○'}</i></button>`).join('')}</div><div class="marketing-hint">💡 BARRIO te ayudará a preparar una propuesta. Tú decides si la publicas.</div><button class="marketing-next" data-marketing-next>Continuar <span>›</span></button></section>`;
 if(step===1)return `<section class="page marketing-page"><div class="back-row"><button data-marketing-back aria-label="Volver">‹</button><span>Impulsa tu negocio</span></div>${marketingProgress()}<div class="marketing-intro"><h1>¿Qué quieres destacar?</h1><p>Escribe el nombre del producto, servicio o novedad. Puedes editar la publicación sugerida después.</p></div><label class="marketing-field-label" for="marketing-product">Producto o servicio</label><textarea id="marketing-product" class="marketing-input" maxlength="100" placeholder="Ej. Pan de muerto recién horneado" data-marketing-product>${esc(state.marketingProduct)}</textarea><div class="marketing-example"><strong>Ejemplo</strong><span>“Latte de mazapán y pan artesanal”</span></div><div class="marketing-ai-note"><span>✦</span><p><strong>Tu asistente preparará una propuesta</strong><br>Usará esta idea y la meta que elegiste para sugerir un texto de campaña.</p></div><button class="marketing-next" data-marketing-next>Continuar <span>›</span></button></section>`;
 if(step===2)return `<section class="page marketing-page"><div class="back-row"><button data-marketing-back aria-label="Volver">‹</button><span>Impulsa tu negocio</span></div>${marketingProgress()}<div class="marketing-intro"><h1>¿A quién quieres llegar?</h1><p>Elige una zona cercana y el tipo de público para esta propuesta.</p></div><label class="marketing-field-label" for="marketing-zone">Zona</label><select id="marketing-zone" class="marketing-select" data-marketing-zone>${['Roma Norte','Condesa','Centro','Del Valle','Coyoacán','Xochimilco'].map(z=>`<option ${state.marketingZone===z?'selected':''}>${z}</option>`).join('')}</select><label class="marketing-field-label">Audiencia</label><div class="marketing-audience-options">${['Vecinos de la zona','Mis seguidores','Toda la comunidad de BARRIO'].map(a=>`<button class="marketing-audience ${state.marketingAudience===a?'selected':''}" data-marketing-audience="${a}"><span>${state.marketingAudience===a?'●':'○'}</span>${a}</button>`).join('')}</div><label class="marketing-field-label">Duración sugerida</label><div class="marketing-duration-options">${['1 día','3 días','7 días'].map(d=>`<button class="duration-choice ${state.marketingDuration===d?'selected':''}" data-marketing-duration="${d}">${d}</button>`).join('')}</div><div class="marketing-hint">La campaña se mostrará a personas de la zona elegida. No se publicará hasta que la apruebes.</div><button class="marketing-next" data-marketing-next>Ver propuesta <span>›</span></button></section>`;
 return `<section class="page marketing-page"><div class="back-row"><button data-marketing-back aria-label="Volver">‹</button><span>Revisa tu campaña</span></div>${marketingProgress()}<div class="marketing-intro"><h1>Tu propuesta está lista</h1><p>Revísala y edítala. La campaña solo se publica cuando tú lo indiques.</p></div><div class="campaign-summary"><span class="campaign-badge">✦ PROPUESTA BARRIO</span><strong>${esc(state.marketingObjective||'Campaña para tu negocio')}</strong><small>📍 ${esc(state.marketingZone)} · ${esc(state.marketingAudience)} · ${esc(state.marketingDuration)}</small></div><label class="marketing-field-label" for="marketing-copy">Texto de la publicación</label><textarea id="marketing-copy" class="marketing-input marketing-copy" maxlength="500" data-marketing-copy>${esc(copy)}</textarea><div class="marketing-ai-note"><span>💡</span><p>Idea destacada: <strong>${esc(state.marketingProduct||'Tu negocio')}</strong><br>Revisa el texto y ajusta lo que quieras antes de publicar.</p></div><div class="marketing-review-actions"><button class="marketing-save" data-marketing-save>Guardar borrador</button><button class="marketing-publish" data-marketing-publish>Publicar campaña</button></div><small class="marketing-footnote">Al publicar, se agregará una publicación de ejemplo al inicio de BARRIO.</small></section>`;
}
function chatPage(){let name=state.chat||'Café Nopal',conv=conversations.find(c=>c.name===name)||{name,emoji:business(name).emoji,msgs:[['theirs','¡Hola! Qué gusto conectar contigo.']]};let msgs=[...conv.msgs,...state.messages.filter(m=>m.chat===name).map(m=>['mine',m.text])];return `<section class="page" style="height:100%;display:flex;flex-direction:column">${`<div class="back-row"><button data-page="messages">‹</button>${avatar(conv.emoji)}<div><strong style="font-size:12px">${name}</strong><small style="display:block;color:#708071;font-size:9px">● En línea</small></div><button class="icon-button" style="margin-left:auto" data-toast="Información del contacto">⋮</button></div>`}<div class="chat-thread">${msgs.map(([who,txt])=>`<div class="bubble ${who}">${esc(txt)}</div>`).join('')}</div><form class="chat-compose" data-chat-form><input placeholder="Escribe un mensaje..." value="${esc(state.chatDraft)}" data-chat-draft /><button aria-label="Enviar">➤</button></form></section>`}
function obSteps(){return ['welcome','role','account','profile',...(state.onboardingRole!=='Quiero comprar'?['business']:[]),'interests','payments','wallet','review']}
function obHeader(){const steps=obSteps();return `<div class="ob-top"><button data-ob-back aria-label="Regresar">‹</button><div class="ob-progress"><i style="width:${Math.round(((state.onboardingStep+1)/steps.length)*100)}%"></i></div><span>${state.onboardingStep+1}/${steps.length}</span></div>`}
function onboardingPage(){const steps=obSteps(),key=steps[state.onboardingStep]||'welcome';if(key==='welcome')return `<section class="page onboarding-page night-welcome"><div class="night-welcome-top"><div class="night-brand">BARRIO<span>✳</span></div><p class="night-tagline">Comercio que conecta</p><h1>Los buenos barrios<br>también brillan de noche.</h1></div><div class="night-welcome-bottom"><p>Descubre los comercios y las historias que hacen único a tu barrio.</p><button class="ob-primary" data-ob-next>Comenzar</button><button class="ob-text-button" data-page="home">Ya tengo cuenta</button></div></section>`;
 const header=obHeader();
 if(key==='role')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>¿Cómo quieres usar BARRIO?</h1><p>Elige el rol que mejor se adapte a ti. Siempre puedes cambiarlo después.</p></div><div class="ob-options">${[['Quiero comprar','Descubre negocios locales, compra productos y apoya tu barrio.','🛍️'],['Tengo un negocio','Publica tu negocio, vende tus productos y llega a más vecinos.','🏪'],['Ambas','Quiero comprar y también tener un negocio.','👥']].map(([t,d,i])=>`<button class="ob-role ${state.onboardingRole===t?'selected':''}" data-ob-role="${t}"><span>${i}</span><div><strong>${t}</strong><small>${d}</small></div><b>${state.onboardingRole===t?'●':'○'}</b></button>`).join('')}</div><button class="ob-primary" data-ob-next>Continuar</button></section>`;
 if(key==='account')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Crea tu cuenta</h1><p>Regístrate para guardar tu perfil y conectar con tu comunidad.</p></div><label class="ob-label">Correo electrónico<input type="email" data-ob-field="accountEmail" value="${esc(state.accountEmail)}" placeholder="ana@ejemplo.com" /></label><label class="ob-label">Teléfono<input type="tel" data-ob-field="accountPhone" value="${esc(state.accountPhone)}" placeholder="+52 55 1234 5678" /></label><label class="ob-label">Contraseña<input type="password" data-ob-field="accountPassword" value="${esc(state.accountPassword)}" placeholder="Crea una contraseña" /></label><label class="account-terms"><input type="checkbox" data-account-terms ${state.accountAccepted?'checked':''} /><span>Acepto los términos de servicio y el aviso de privacidad.</span></label><div class="account-divider"><i></i>O continúa con<i></i></div><div class="account-social"><button data-toast="Acceso con Google disponible en la app final">G</button><button data-toast="Acceso con Apple disponible en la app final">●</button></div><button class="ob-primary" data-ob-next>Crear cuenta</button></section>`;
 if(key==='profile')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Cuéntanos de ti</h1><p>Esta información nos ayuda a personalizar tu experiencia en BARRIO.</p></div><div class="ob-photo">👩🏻<button data-toast="Elegir foto próximamente">📷</button></div><label class="ob-label">Nombre<input data-ob-field="name" value="${esc(state.onboardingName)}" placeholder="Tu nombre" /></label><label class="ob-label">Colonia<select data-ob-field="zone">${['Roma Norte, CDMX','Condesa, CDMX','Centro, CDMX','Del Valle, CDMX','Coyoacán, CDMX','Xochimilco, CDMX'].map(z=>`<option ${state.onboardingZone===z?'selected':''}>${z}</option>`).join('')}</select></label><label class="ob-label">Cuéntanos un poco de ti<textarea data-ob-field="bio" placeholder="¿Qué te gusta de tu comunidad?">${esc(state.onboardingBio)}</textarea></label><button class="ob-primary" data-ob-next>Continuar</button></section>`;
 if(key==='business')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Tu negocio</h1><p>Cuéntanos sobre tu negocio para que tus vecinos puedan conocerte.</p></div><div class="ob-business-photo"><span>CAFÉ NOPAL</span><button data-toast="Elegir foto del negocio próximamente">📷</button></div><label class="ob-label">Nombre del negocio<input data-ob-field="shopName" value="${esc(state.shopName)}" /></label><label class="ob-label">Giro<select data-ob-field="shopKind">${['Cafetería','Tienda','Restaurante','Servicios','Panadería','Flores y plantas','Otro'].map(t=>`<option ${state.shopKind===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="ob-label">Colonia<select data-ob-field="shopZone">${['Roma Norte, CDMX','Condesa, CDMX','Centro, CDMX','Del Valle, CDMX','Coyoacán, CDMX','Xochimilco, CDMX'].map(z=>`<option ${state.onboardingZone===z?'selected':''}>${z}</option>`).join('')}</select></label><label class="ob-label">¿Qué ofreces?<textarea data-ob-field="shopBio">${esc(state.shopBio)}</textarea></label><button class="ob-primary" data-ob-next>Continuar</button></section>`;
 if(key==='interests')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Elige tus intereses</h1><p>Selecciona categorías para ver comercios y publicaciones relevantes.</p></div><div class="interest-grid">${[['Cafeterías','☕'],['Alimentos','🥐'],['Tiendas','🏪'],['Servicios','🛠️'],['Flores','🌷'],['Belleza','💅'],['Hogar','🪴'],['Otros','•••']].map(([t,i])=>`<button class="interest-tile ${state.interests.includes(t)?'selected':''}" data-interest="${t}"><span>${i}</span><strong>${t}</strong>${state.interests.includes(t)?'<i>✓</i>':''}</button>`).join('')}</div><p class="ob-hint">Puedes elegir varias categorías y cambiarlas después.</p><button class="ob-primary" data-ob-next>Continuar</button></section>`;
 if(key==='payments')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Métodos de pago y cobro</h1><p>Elige cómo quieres pagar o recibir pagos en tu negocio. Puedes activar varios métodos.</p></div><div class="payment-method-list">${[['Tarjeta','Acepta pagos con tarjeta en tu negocio.','💳'],['SPEI','Recibe pagos por transferencia electrónica.','🏦'],['NFC','Pago sin contacto con teléfono en el local.',')))'],['Cripto','Opcional. Puedes configurarlo después.','₿']].map(([t,d,i])=>`<button class="payment-method-card ${state.paymentMethods[t]?'enabled':''}" data-ob-payment="${t}"><span>${i}</span><div><strong>${t==='NFC'?'NFC en el local':t}</strong><small>${d}</small></div><i>${state.paymentMethods[t]?'●':'○'}</i></button>`).join('')}</div><div class="ob-callout">ⓘ Puedes cambiar estos métodos después desde la configuración de tu negocio.</div><button class="ob-primary" data-ob-next>Continuar</button></section>`;
 if(key==='wallet')return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Conecta tu wallet <small>(opcional)</small></h1><p>Vincula una wallet para explorar opciones Web3. También puedes continuar sin conectarla.</p></div><div class="wallet-options">${[['MetaMask','🦊'],['WalletConnect','🔷'],['Coinbase Wallet','🔵']].map(([t,i])=>`<button class="wallet-option ${state.wallet===t?'selected':''}" data-ob-wallet="${t}"><span>${i}</span><strong>${t}</strong><b>${state.wallet===t?'Conectada':'›'}</b></button>`).join('')}</div>${state.wallet?'<div class="ob-callout">✓ Wallet de demostración conectada en esta sesión.</div>':'<div class="ob-callout">No tienes wallet? No hay problema. Puedes usar BARRIO sin conectarla.</div>'}<button class="ob-outline" data-ob-skip>Conectar después</button><button class="ob-primary" data-ob-next>Continuar</button></section>`;
 return `<section class="page onboarding-page">${header}<div class="ob-title"><h1>Revisa tu perfil</h1><p>Verifica que todo esté correcto antes de crear tu perfil.</p></div><div class="ob-review-cover ${state.onboardingRole==='Quiero comprar'?'customer-cover':''}"><span>${state.onboardingRole==='Quiero comprar'?esc(state.onboardingName):esc(state.shopName)}</span></div><div class="ob-review-card"><div class="ob-review-avatar">👩🏻</div><strong>${state.onboardingRole==='Quiero comprar'?esc(state.onboardingName):esc(state.shopName)}</strong><span>${state.onboardingRole==='Quiero comprar'?'Cliente':state.shopKind} · ${esc(state.onboardingZone)}</span><p>${esc(state.onboardingRole==='Quiero comprar'?state.onboardingBio:state.shopBio)}</p><div class="ob-review-label">Mis intereses</div><div class="ob-tags">${state.interests.map(i=>`<span>${i}</span>`).join('')||'<span>Sin categorías</span>'}</div><div class="ob-review-label">Métodos</div><div class="ob-tags">${Object.entries(state.paymentMethods).filter(([,v])=>v).map(([k])=>`<span>${k}</span>`).join('')||'<span>Sin métodos</span>'}</div>${state.wallet?`<small>Wallet: ${state.wallet}</small>`:''}</div><button class="ob-primary" data-ob-complete>Crear mi perfil</button><button class="ob-text-button" data-ob-back>Revisar datos</button></section>`}
const productsForShop=()=>catalog().filter(p=>state.shopFilter==='Todos'||p.category===state.shopFilter);
function shopDiscover(){const q=state.shopQuery.toLowerCase();const products=productsForShop().filter(p=>!q||`${p.name} ${p.category}`.toLowerCase().includes(q));const stores=businesses.slice(0,3).filter(b=>!q||`${b.name} ${b.zone} ${b.type}`.toLowerCase().includes(q));return `<section class="page shop-page"><div class="shop-topline"><div class="shop-brand">BARRIO<span>✳</span></div><button class="icon-button" data-page="cart" aria-label="Carrito">🛒${state.cart.length?`<i class="cart-count">${state.cart.reduce((a,c)=>a+c.qty,0)}</i>`:''}</button></div><div class="shop-welcome"><h1>Hola, Ana ☀️</h1><p>Descubre y apoya los negocios de tu barrio.</p></div>${searchBox(state.shopQuery,'Buscar comercios o productos...','shop-search-change','shop-search')}<div class="shop-category-row">${['Todos','Bebidas','Comida','Postres'].map(k=>`<button class="shop-filter ${state.shopFilter===k?'selected':''}" data-shop-filter="${k}">${k}</button>`).join('')}</div><div class="section-heading"><h2>Comercios cerca de ti</h2><button class="text-button" data-page="map">Ver todos ›</button></div><div class="shop-store-row">${stores.map(b=>`<button class="shop-store-card" data-page="storefront"><span class="shop-store-image ${photoClass(b)}"></span><strong>${esc(b.name)}</strong><small>★ 4.8 · ${esc(b.zone)}</small></button>`).join('')}</div><div class="section-heading"><h2>Productos populares</h2><button class="text-button" data-page="cart">Mi carrito (${state.cart.reduce((a,c)=>a+c.qty,0)})</button></div><div class="product-grid">${products.length?products.map(p=>`<button class="shop-product-card" data-product-id="${p.id}"><span class="product-photo">${p.emoji}</span><strong>${esc(p.name)}</strong><small>$${p.price} MXN · Café Nopal</small><span class="product-rating">★ 4.9</span></button>`).join(''):'<div class="empty-state">No encontramos productos en esta categoría.</div>'}</div><button class="shop-owner-link" data-page="merchant-dashboard">¿Tienes un negocio? <b>Adminístralo en BARRIO ›</b></button></section>`}
function storefrontPage(){const prods=catalog();return `<section class="page storefront-page"><div class="store-cover"><button class="cover-back" data-page="shop-discover">‹</button><span>CAFÉ NOPAL</span><button class="store-more" data-toast="Más opciones próximamente">···</button></div><div class="store-summary"><div class="store-avatar">🌵</div><div><h1>Café Nopal <span class="verified">●</span></h1><p>★ 4.8 (120 reseñas) · 0.3 km</p><small>⌖ Roma Norte, CDMX</small></div></div><div class="store-tags"><span>Cafés</span><span>Panadería</span><span>Desayunos</span><span>Local</span></div><div class="store-actions"><button class="secondary-button" data-connect>${state.connected?'✓ Conectado':'♧ Conectar'}</button><button class="secondary-button" data-chat="Café Nopal">▢ Mensaje</button></div><div class="store-tabs"><button class="selected">Productos</button><button data-toast="Información del negocio">Acerca de</button><button data-toast="Aún no hay reseñas">Reseñas</button></div><div class="section-heading"><h2>Productos del día</h2><span class="store-open">● Abierto</span></div><div class="product-grid">${prods.map(p=>`<button class="shop-product-card" data-product-id="${p.id}"><span class="product-photo">${p.emoji}</span><strong>${esc(p.name)}</strong><small>$${p.price} MXN</small></button>`).join('')}</div></section>`}
function productDetailPage(){const p=catalog().find(x=>x.id===state.selectedProductId)||catalog()[0];return `<section class="page product-detail-page"><div class="back-row"><button data-page="storefront">‹</button><span>Producto</span><button class="icon-button product-cart-shortcut" data-page="cart">🛒</button></div><div class="product-hero">${p.emoji}</div><div class="product-seller">Café Nopal · Roma Norte</div><h1>${esc(p.name)}</h1><strong class="product-price">$${p.price} MXN</strong><p class="product-desc">Preparado con ingredientes locales y de temporada. Elaborado artesanalmente en nuestro barrio.</p><div class="product-values"><span>🌱<small>Ingredientes locales</small></span><span>♡<small>Hecho con cuidado</small></span><span>☀️<small>Del día</small></span></div><div class="quantity-control"><button data-detail-qty="-">−</button><strong>${state.detailQty||1}</strong><button data-detail-qty="+">＋</button></div><button class="ob-primary add-cart-button" data-add-cart>🛒 Agregar al carrito</button></section>`}
function cartPage(){const items=state.cart.map(line=>({...line,product:catalog().find(p=>p.id===line.id)})).filter(x=>x.product);const total=items.reduce((sum,x)=>sum+x.product.price*x.qty,0);return `<section class="page cart-page"><div class="back-row"><button data-page="shop-discover">‹</button><strong>Tu carrito</strong><button class="cart-clear" data-clear-cart>Vaciar</button></div>${items.length?`<div class="cart-items">${items.map(x=>`<div class="cart-item"><span class="cart-item-photo">${x.product.emoji}</span><div class="cart-item-main"><strong>${esc(x.product.name)}</strong><small>$${x.product.price} MXN</small><div class="cart-qty"><button data-cart-qty="${x.id}:-">−</button><b>${x.qty}</b><button data-cart-qty="${x.id}:+">＋</button></div></div><b class="cart-line-total">$${x.product.price*x.qty}</b><button class="remove-cart" data-cart-remove="${x.id}" aria-label="Quitar">×</button></div>`).join('')}</div><button class="cart-note" data-toast="Nota del pedido: próximamente">✎ Agregar nota para el comercio <span>›</span></button><div class="cart-total"><span>Subtotal</span><b>$${total} MXN</b><span>Envío</span><b>Gratis</b><strong>Total</strong><strong>$${total} MXN</strong></div><button class="ob-primary" data-page="checkout">Continuar</button>`:'<div class="empty-state">Tu carrito está vacío.<br>Explora productos locales para empezar.</div><button class="ob-primary" data-page="shop-discover">Explorar productos</button>'}</section>`}
function checkoutPage(){const items=state.cart.map(l=>({...l,product:catalog().find(p=>p.id===l.id)})).filter(x=>x.product);const total=items.reduce((s,x)=>s+x.product.price*x.qty,0);const methods=[['Transferencia SPEI','🏦'],['Efectivo','💵'],['HBAR · Red Hedera','₿'],['Tarjeta · Próximamente','💳'],['NFC · Próximamente',')))']];return `<section class="page checkout-page"><div class="back-row"><button data-page="cart">‹</button><strong>Finaliza tu compra</strong></div><div class="checkout-section"><h2>Método de entrega</h2><div class="checkout-choice-row">${[['Recoger en tienda','🏪','Listo en 15–20 min'],['Entrega local','🚲','En 30–45 min']].map(([t,i,d])=>`<button class="checkout-choice ${state.delivery===t?'selected':''}" data-delivery="${t}"><span>${i}</span><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><div class="checkout-store"><span>⌖</span><div><strong>Café Nopal</strong><small>Roma Norte, CDMX</small></div><button data-toast="Cambiar ubicación próximamente">›</button></div>${state.delivery==='Entrega local'?`<label class="ob-label">Dirección de entrega<input placeholder="Calle, número y colonia" value="${esc(state.deliveryAddress)}" data-delivery-address /></label>`:''}</div><div class="checkout-section"><h2>Método de pago</h2><div class="checkout-payments">${methods.map(([t,i])=>{const upcoming=t.includes('Próximamente'),selected=state.payment===t;return `<button class="checkout-payment ${selected?'selected':''} ${upcoming?'payment-upcoming':''}" ${upcoming?'disabled aria-disabled="true"':''} ${!upcoming?`data-checkout-payment="${t}"`:''}><span>${i}</span>${t}<b>${selected?'●':upcoming?'◷':'○'}</b></button>`}).join('')}</div>${state.payment.startsWith('HBAR')?`<div class="crypto-risk-demo"><div><strong>HBAR en Hedera</strong><small>Conecta tu propia billetera al continuar.</small></div><p>Modo de demostración: elige si esta operación pasa sin alerta o requiere revisión antifraude.</p><div class="crypto-risk-options"><button class="${state.cryptoRiskMode==='normal'?'selected':''}" data-crypto-risk-mode="normal">Sin alerta</button><button class="${state.cryptoRiskMode==='suspicious'?'selected':''}" data-crypto-risk-mode="suspicious">Simular operación sospechosa</button></div><small>reCeption no está conectado; esta opción solo muestra la ruta visual.</small></div>`:''}</div><div class="checkout-total"><span>Total a pagar</span><strong>$${total} MXN</strong></div><button class="ob-primary" data-review-payment>Continuar al pago</button><small class="secure-note">🔒 Pago local de demostración; no se realiza ningún cargo ni transferencia.</small></section>`}
function processingPage(){const total=state.cart.reduce((s,l)=>{const p=catalog().find(x=>x.id===l.id);return s+(p?p.price*l.qty:0)},0);const crypto=state.payment.startsWith('HBAR');const cash=state.payment==='Efectivo';return `<section class="page payment-processing"><div class="back-row"><button data-page="checkout">‹</button><strong>${crypto?'Confirmar con mi billetera':'Confirma tu pago'}</strong></div><div class="payment-success-icon">${crypto?'₿':cash?'💵':'🔒'}</div><h1>${crypto?'Revisa en tu billetera Hedera':cash?'Pago en efectivo':'Revisa tu pedido'}</h1><p>${crypto?'En la app real, tu billetera mostrará el importe y solicitará tu autorización para pagar con HBAR.':cash?'Pagarás al recibir tu pedido o recogerlo en el comercio.':`Confirma tu pedido con ${esc(state.payment)} para simular el pago.`}</p><div class="payment-recap"><span>Comercio</span><b>Café Nopal</b><span>Método</span><b>${esc(state.payment)}</b>${crypto?'<span>Red</span><b>Hedera</b>':''}<span>Total</span><b>$${total} MXN</b></div><button class="ob-primary" data-confirm-order>${crypto?'Simular autorización en billetera':cash?'Confirmar pedido':'Confirmar pedido'}</button><small class="secure-note">La confirmación es local y de demostración. No se conecta una billetera.</small></section>`}
function cryptoVerificationPage(){const total=state.cart.reduce((s,l)=>{const p=catalog().find(x=>x.id===l.id);return s+(p?p.price*l.qty:0)},0);return `<section class="page payment-processing crypto-verification"><div class="back-row"><button data-crypto-cancel>‹</button><strong>Seguridad del pago</strong></div><div class="payment-success-icon">🛡️</div><h1>Verificación adicional</h1><p>Esta operación HBAR fue marcada como sospechosa en la simulación. Verifica antes de continuar a tu billetera.</p><div class="payment-recap"><span>Comercio</span><b>Café Nopal</b><span>Método</span><b>HBAR · Red Hedera</b><span>Total</span><b>$${total} MXN</b></div><div class="crypto-review-card"><strong>reCeption · Revisión antifraude</strong><small>La verificación es una demostración visual. No se consultan servicios externos.</small></div><button class="ob-primary" data-crypto-verify>Simular verificación aprobada</button><button class="ob-outline" data-crypto-cancel>Cancelar y no enviar el pago</button><small class="secure-note">Tu billetera aún no recibió una solicitud de autorización.</small></section>`}
function orderConfirmationPage(){const o=state.currentOrder||{id:`BR-${state.orderNumber}`,amount:0,items:[]};return `<section class="page order-confirmation"><div class="order-success-mark">✓</div><h1>¡Pedido confirmado!</h1><p>Café Nopal ha recibido tu pedido.</p><div class="order-number-card"><small>Número de pedido</small><strong>${o.id}</strong><button data-toast="Número copiado">▢</button></div><div class="order-store-card"><span>🌵</span><div><strong>Café Nopal</strong><small>Roma Norte, CDMX</small><small>${state.delivery} · Hoy, 12:30 PM</small></div></div><div class="order-total-row"><span>${o.items?.length||0} productos</span><strong>$${o.amount} MXN</strong></div><button class="ob-primary" data-page="customer-order-detail">Ver pedido</button><button class="ob-outline" data-page="shop-discover">Seguir explorando</button></section>`}
function myOrdersPage(){return `<section class="page"><div class="back-row"><button data-page="profile">‹</button><strong>Mis pedidos</strong></div>${demoOrders.map(o=>`<button class="merchant-order-row customer-past-order" data-customer-order="${o.id}"><span class="order-icon">🌵</span><span><strong>Café Nopal · ${o.id}</strong><small>${o.time} · $${o.amount} MXN</small></span><i class="status-pill ${o.status.toLowerCase()}">${o.status}</i><b>›</b></button>`).join('')||'<div class="empty-state">Aún no tienes pedidos.</div>'}</section>`}
function customerOrderPage(){let o=state.currentOrder;if((!o||state.customerOrder)&&state.currentOrder?.id!==state.customerOrder){const past=demoOrders.find(x=>x.id===state.customerOrder);if(past)o={id:past.id,amount:past.amount,items:[{name:'Café de olla',emoji:'☕',qty:1,price:past.amount}]}}o=o||{id:`BR-${state.orderNumber}`,amount:0,items:[]};return `<section class="page customer-order-page"><div class="back-row"><button data-page="${state.customerOrder?'my-orders':'order-confirmation'}">‹</button><strong>Detalle del pedido</strong></div><div class="order-status-card"><span>●</span><div><strong>Pedido recibido</strong><small>El comercio está preparando tu compra.</small></div></div><h2>${o.id}</h2><div class="order-store-card"><span>🌵</span><div><strong>Café Nopal</strong><small>${state.delivery} · Roma Norte, CDMX</small></div></div><div class="order-products">${(o.items||[]).map(x=>`<div><span>${x.emoji} ${esc(x.name)} × ${x.qty}</span><b>$${x.price*x.qty} MXN</b></div>`).join('')}</div><div class="checkout-total"><span>Total pagado</span><strong>$${o.amount} MXN</strong></div><button class="ob-outline" data-chat="Café Nopal">▢ Escribir al comercio</button></section>`}
function merchantDashboard(){return `<section class="page merchant-page"><div class="merchant-top"><button class="merchant-menu" data-page="profile">‹</button><div class="merchant-brand">BARRIO<span>✳</span></div><button class="icon-button" data-toast="No tienes notificaciones nuevas">♧</button></div><div class="merchant-greeting"><div class="merchant-logo">☕</div><div><h1>¡Hola, Café Nopal!</h1><p>Tu negocio hoy · <span>● Abierto</span></p></div></div><div class="merchant-metrics"><div><span>💵</span><strong>$1,250</strong><small>MXN · Ventas de hoy</small></div><div><span>📦</span><strong>12</strong><small>Pedidos</small></div><div><span>👥</span><strong>5</strong><small>Nuevos clientes</small></div><div><span>▥</span><strong>320</strong><small>Visitas a tu tienda</small></div></div><div class="section-heading"><h2>Acciones rápidas</h2></div><div class="merchant-quick-grid">${[['＋','Agregar producto','merchant-product-form'],['▣','Ver pedidos','merchant-orders'],['🏷️','Promociones','marketing'],['▥','Ver estadísticas','merchant-analytics'],['↗','Compartir tienda','storefront']].map(([i,t,p])=>`<button data-page="${p}"><span>${i}</span><small>${t}</small></button>`).join('')}</div><div class="section-heading"><h2>Pedidos recientes</h2><button class="text-button" data-page="merchant-orders">Ver todos ›</button></div>${demoOrders.slice(0,2).map(orderRow).join('')}</section>`}
function orderRow(o){return `<button class="merchant-order-row" data-order-id="${o.id}"><span class="order-icon">${o.emoji||'🛍️'}</span><span><strong>${o.id}</strong><small>${esc(o.customer)} · ${esc(o.items)}</small></span><i class="status-pill ${o.status.toLowerCase()}">${o.status}</i><b>›</b></button>`}
function merchantProductsPage(){const q=(state.merchantSearch||'').toLowerCase();const list=state.merchantProducts.filter(p=>(state.merchantFilter==='Todos'||p.category===state.merchantFilter)&&(!q||`${p.name} ${p.category}`.toLowerCase().includes(q)));return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-dashboard">‹</button><strong>Productos</strong><button class="merchant-add" data-new-product>＋ Agregar</button></div>${searchBox(state.merchantSearch||'','Buscar productos...','merchant-product-search')}<div class="merchant-filters">${['Todos','Bebidas','Comida','Postres'].map(t=>`<button class="${state.merchantFilter===t?'selected':''}" data-merchant-filter="${t}">${t}</button>`).join('')}</div><div class="section-heading"><h2>Inventario (${list.length})</h2></div>${list.length?list.map(p=>`<button class="inventory-row" data-edit-product="${p.id}"><span class="inventory-photo">${p.emoji}</span><span class="inventory-copy"><strong>${esc(p.name)}</strong><small>$${p.price} MXN</small><i class="${p.stock<10?'low':''}">● ${p.stock<10?'Stock bajo':'En existencia'} (${p.stock})</i></span><span class="inventory-menu">···</span></button>`).join(''):'<div class="empty-state">No hay productos en esta categoría.</div>'}</section>`}
function merchantProductForm(){const p=state.merchantProducts.find(x=>x.id===state.editingProductId);const f=p||state.merchantForm;return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-products">‹</button><strong>${p?'Editar producto':'Nuevo producto'}</strong></div><button class="product-upload" data-toast="La carga de fotos es decorativa en esta demo"><span>📷</span>Agrega una foto de tu producto</button><label class="ob-label">Nombre del producto<input data-product-field="name" value="${esc(f.name)}" placeholder="Ej. Café de olla" /></label><label class="ob-label">Precio (MXN)<input data-product-field="price" type="number" min="1" value="${esc(f.price)}" placeholder="$ 0" /></label><label class="ob-label">Categoría<select data-product-field="category">${['Bebidas','Comida','Postres'].map(x=>`<option ${f.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="ob-label">Descripción corta<textarea data-product-field="description" placeholder="Describe tu producto (máx. 150 caracteres)">${esc(f.description||p?.description||'')}</textarea></label><label class="ob-label">Existencia<input data-product-field="stock" type="number" min="0" value="${f.stock??p?.stock??''}" placeholder="Ej. 20" /></label><button class="ob-primary" data-save-product>Guardar producto</button></section>`}
function merchantOrdersPage(){const statuses=['Nuevos','Preparando','Listos','Completados'];const keys={Nuevos:'Nuevo',Preparando:'Preparando',Listos:'Listo',Completados:'Completado'};const q=(state.orderSearch||'').toLowerCase();const list=demoOrders.filter(o=>(state.merchantOrderFilter==='Todos'||o.status===keys[state.merchantOrderFilter])&&(!q||`${o.id} ${o.customer}`.toLowerCase().includes(q)));return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-dashboard">‹</button><strong>Pedidos</strong></div>${searchBox(state.orderSearch||'','Buscar por cliente o número','merchant-order-search')}<div class="merchant-filters order-filters">${statuses.map(s=>`<button class="${state.merchantOrderFilter===s?'selected':''}" data-order-filter="${s}">${s}</button>`).join('')}</div>${list.length?list.map(orderRow).join(''):'<div class="empty-state">No hay pedidos en este estado.</div>'}</section>`}
function merchantOrderDetail(){const o=demoOrders.find(x=>x.id===state.selectedOrder)||demoOrders[0];const items=state.currentOrder?.id===o.id?state.currentOrder.items:[{name:'Café de olla',emoji:'☕',qty:1,price:45},{name:'Pan artesanal',emoji:'🥖',qty:1,price:35}];const subtotal=items.reduce((sum,x)=>sum+x.price*x.qty,0);return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-orders">‹</button><strong>Pedido ${o.id}</strong><button class="icon-button" data-toast="Opciones del pedido">···</button></div><div class="customer-order-header"><div class="customer-avatar">👩🏻</div><div><strong>${esc(o.customer)}</strong><small>☎ +52 55 1234 5678</small></div><button data-chat="${esc(o.customer)}">▢</button></div><div class="order-pickup"><strong>⌖ Retiro en tienda</strong><small>Roma Norte, CDMX · Hace 5 minutos</small></div><div class="section-heading"><h2>Artículos (${items.length})</h2><button class="text-button" data-toast="Editar artículos próximamente">Editar</button></div>${items.map(x=>`<div class="merchant-line-item"><span>${x.emoji} ${esc(x.name)} ×${x.qty}</span><b>$${x.price*x.qty} MXN</b></div>`).join('')}<div class="cart-total"><span>Subtotal</span><b>$${subtotal} MXN</b><span>Tarifa de la app</span><b>$${Math.max(0,o.amount-subtotal)} MXN</b><strong>Total</strong><strong>$${o.amount} MXN</strong></div><div class="order-progress"><span class="${o.status==='Nuevo'?'current':''}">Nuevo</span><i></i><span class="${o.status==='Preparando'?'current':''}">Preparando</span><i></i><span class="${o.status==='Listo'?'current':''}">Listo</span><i></i><span class="${o.status==='Completado'?'current':''}">Completado</span></div><button class="ob-primary" data-advance-order>${o.status==='Nuevo'?'Aceptar y preparar':o.status==='Preparando'?'Marcar como listo':o.status==='Listo'?'Marcar como completado':'Pedido completado ✓'}</button><button class="ob-outline" data-chat="${esc(o.customer)}">Escribir a cliente</button></section>`}
function merchantAnalytics(){return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-dashboard">‹</button><strong>Ventas</strong><button class="merchant-select" data-toast="Periodo: últimos 30 días">Últimos 30 días⌄</button></div><div class="merchant-metrics analytics-metrics"><div><strong>$24,850</strong><small>MXN · Ventas totales</small><i>↗ +18%</i></div><div><strong>320</strong><small>Pedidos</small><i>↗ +12%</i></div><div><strong>85</strong><small>Nuevos clientes</small><i>↗ +25%</i></div><div><strong>1,240</strong><small>Visitas a tu tienda</small><i>↗ +15%</i></div></div><div class="section-heading"><h2>Ventas diarias</h2></div><div class="sales-chart" aria-label="Gráfica visual de ventas de los últimos treinta días">${[28,44,35,52,41,62,49,75,58,90,48,70,55,83].map(h=>`<i style="height:${h}%"></i>`).join('')}</div><div class="chart-caption"><span>1 Mar</span><span>7 Mar</span><span>14 Mar</span><span>21 Mar</span><span>28 Mar</span></div><div class="section-heading"><h2>Productos más vendidos</h2><button class="text-button" data-page="merchant-products">Ver productos ›</button></div>${state.merchantProducts.slice(0,3).map(p=>`<div class="top-product-row"><span>${p.emoji}</span><strong>${esc(p.name)}</strong><small>${Math.max(18,p.stock*3)} vendidos</small><i style="width:${Math.min(88,p.stock*1.5)}%"></i></div>`).join('')}</section>`}
function merchantCustomers(){return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-more">‹</button><strong>Clientes</strong></div>${searchBox(state.customerSearch||'','Buscar clientes','merchant-customer-search')}${[['👩🏻','Ana Ramírez','12 pedidos · $1,240'],['👨🏽','Diego Morales','8 pedidos · $980'],['👩🏽','Mariana Torres','5 pedidos · $650'],['👨🏻','Luis T.','4 pedidos · $520'],['👩🏼','Sofía R.','3 pedidos · $410']].filter(x=>!state.customerSearch||x[1].toLowerCase().includes(state.customerSearch.toLowerCase())).map(([i,n,d])=>`<button class="customer-row" data-chat="${n}"><span>${i}</span><strong>${n}<small>${d}</small></strong><b>›</b></button>`).join('')||'<div class="empty-state">No encontramos clientes.</div>'}</section>`}
function merchantMore(){return `<section class="page merchant-page"><div class="back-row"><button data-page="merchant-dashboard">‹</button><strong>Más herramientas</strong></div><div class="merchant-more-menu">${[['👥','Clientes','merchant-customers'],['🌐','Perfil público de la tienda','storefront'],['📣','Impulsa tu negocio','marketing'],['↩','Volver a BARRIO','profile']].map(([i,t,p])=>`<button class="menu-row" data-page="${p}"><span>${i}</span>${t}<b class="arrow">›</b></button>`).join('')}</div></section>`}
function render(){navRender();const pages={home, map:mapPage, business:businessPage, messages:messagesPage, compose:composePage, profile:profilePage, marketing:marketingPage, chat:chatPage, onboarding:onboardingPage,'shop-discover':shopDiscover,storefront:storefrontPage,'product-detail':productDetailPage,cart:cartPage,checkout:checkoutPage,'payment-processing':processingPage,'crypto-verification':cryptoVerificationPage,'order-confirmation':orderConfirmationPage,'customer-order-detail':customerOrderPage,'my-orders':myOrdersPage,'merchant-dashboard':merchantDashboard,'merchant-products':merchantProductsPage,'merchant-product-form':merchantProductForm,'merchant-orders':merchantOrdersPage,'merchant-order-detail':merchantOrderDetail,'merchant-analytics':merchantAnalytics,'merchant-customers':merchantCustomers,'merchant-more':merchantMore};app.innerHTML=(pages[state.page]||home)();app.scrollTop=0}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-page],[data-open-business],[data-marker]');if(!el)return;if(el.dataset.page){setPage(el.dataset.page);return}if(el.dataset.openBusiness){openBusiness(el.dataset.openBusiness);return}if(el.dataset.marker){state.selectedBusiness=el.dataset.marker;state.mapDetailOpen=true;render();return}if(el.dataset.filter){state.mapFilter=el.dataset.filter;state.mapDetailOpen=false;render();return}if(el.dataset.messageFilter){state.messageFilter=el.dataset.messageFilter;render();return}if(el.dataset.chat){state.chat=el.dataset.chat;state.page='chat';render();return}if(el.hasAttribute('data-connect')){state.connected=!state.connected;render();showToast(state.connected?'Ya estás conectado con este comercio':'Dejaste de seguir este comercio');return}if(el.dataset.postType){state.postType=el.dataset.postType;render();return}if(el.dataset.tool){state.tools[el.dataset.tool]=!state.tools[el.dataset.tool];if(el.dataset.tool==='Fotos'&&state.tools.Fotos)showToast('Foto de ejemplo agregada');else showToast(`${el.dataset.tool}: ${state.tools[el.dataset.tool]?'activado':'quitado'}`);render();return}if(el.hasAttribute('data-audience')){state.audience=state.audience==='Toda la comunidad de BARRIO'?'Solo mis conexiones':'Toda la comunidad de BARRIO';render();return}if(el.hasAttribute('data-publish')){if(!state.composeText.trim()){showToast('Escribe algo para compartir con tu comunidad');return}state.posts.unshift({name:'Café Nopal',emoji:'🌵',meta:'Ahora · Roma Norte',text:state.composeText.trim(),image:state.tools.Fotos?'📷':'',photo:state.tools.Fotos,type:state.postType});state.composeText='';state.tools={};setPage('home');showToast('¡Tu publicación ya está en la comunidad!');return}if(el.dataset.businessTab){state.businessTab=el.dataset.businessTab;render();return}if(el.dataset.toast){showToast(el.dataset.toast);return}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-marketing-objective],[data-marketing-next],[data-marketing-back],[data-marketing-audience],[data-marketing-duration],[data-marketing-save],[data-marketing-publish]');if(!el)return;if(el.dataset.marketingObjective){state.marketingObjective=el.dataset.marketingObjective;render();return}if(el.hasAttribute('data-marketing-back')){state.marketingStep=Math.max(0,state.marketingStep-1);render();return}if(el.hasAttribute('data-marketing-next')){if(state.marketingStep===0&&!state.marketingObjective){showToast('Elige una meta para continuar');return}if(state.marketingStep===1&&!state.marketingProduct.trim()){showToast('Cuéntanos qué producto o servicio quieres destacar');return}if(state.marketingStep===2){const product=state.marketingProduct.trim();const openings={'Atraer clientes':`¿Buscas algo rico y hecho en el barrio? `,'Anunciar un producto':`¡Tenemos algo nuevo para ti! `,'Promover una oferta':`Esta semana tenemos algo especial: `,'Invitar a volver':`Nos dará mucho gusto verte de nuevo. `};state.marketingCopy=`${openings[state.marketingObjective]||''}${product}. Visítanos en Café Nopal, en ${state.marketingZone}. ¡Te esperamos! ☕`;}state.marketingStep=Math.min(3,state.marketingStep+1);render();return}if(el.dataset.marketingAudience){state.marketingAudience=el.dataset.marketingAudience;render();return}if(el.dataset.marketingDuration){state.marketingDuration=el.dataset.marketingDuration;render();return}if(el.hasAttribute('data-marketing-save')){state.marketingDraft={objective:state.marketingObjective,product:state.marketingProduct,zone:state.marketingZone,audience:state.marketingAudience,duration:state.marketingDuration,copy:state.marketingCopy};showToast('Borrador guardado durante esta sesión');return}if(el.hasAttribute('data-marketing-publish')){const copy=state.marketingCopy.trim();if(!copy){showToast('Agrega un texto antes de publicar');return}state.posts.unshift({name:'Café Nopal',emoji:'🌵',meta:`Campaña · ${state.marketingZone} · Ahora`,text:copy,image:'',type:'Novedad'});state.marketingDraft=null;state.marketingStep=0;state.marketingObjective='';state.marketingProduct='';state.marketingCopy='';setPage('home');showToast('¡Campaña publicada en tu comunidad!');return}});
document.addEventListener('input',e=>{if(e.target.matches('[data-marketing-product]'))state.marketingProduct=e.target.value;if(e.target.matches('[data-marketing-copy]'))state.marketingCopy=e.target.value});
document.addEventListener('change',e=>{if(e.target.matches('[data-marketing-zone]'))state.marketingZone=e.target.value});
document.addEventListener('input',e=>{let a=e.target.dataset.action;if(a==='search-change'){state.query=e.target.value;const pos=e.target.selectionStart;render();let n=app.querySelector('[data-action="search-change"]');n?.focus();n?.setSelectionRange(pos,pos)}else if(a==='map-search-change'){state.mapQuery=e.target.value;const pos=e.target.selectionStart;render();let n=app.querySelector('[data-action="map-search-change"]');n?.focus();n?.setSelectionRange(pos,pos)}else if(a==='message-search-change'){state.messageQuery=e.target.value;const pos=e.target.selectionStart;render();let n=app.querySelector('[data-action="message-search-change"]');n?.focus();n?.setSelectionRange(pos,pos)}else if(e.target.matches('[data-compose-text]')){state.composeText=e.target.value;document.getElementById('charcount').textContent=state.composeText.length}else if(e.target.matches('[data-chat-draft]'))state.chatDraft=e.target.value});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-chat-form]'))return;e.preventDefault();let text=state.chatDraft.trim();if(!text)return;state.messages.push({chat:state.chat||'Café Nopal',text});state.chatDraft='';render()});
document.addEventListener('click',e=>{const el=e.target.closest('[data-owner-page],[data-ob-back],[data-ob-next],[data-ob-role],[data-ob-payment],[data-ob-wallet],[data-ob-skip],[data-ob-complete],[data-interest],[data-shop-filter],[data-product-id],[data-detail-qty],[data-add-cart],[data-cart-qty],[data-cart-remove],[data-clear-cart],[data-delivery],[data-checkout-payment],[data-crypto-risk-mode],[data-crypto-verify],[data-crypto-cancel],[data-review-payment],[data-confirm-order],[data-order-id],[data-order-filter],[data-customer-order],[data-advance-order],[data-merchant-filter],[data-edit-product],[data-new-product],[data-save-product]');if(!el)return;
 if(el.dataset.ownerPage){setPage(el.dataset.ownerPage);return}
 if(el.hasAttribute('data-ob-back')){state.onboardingStep=Math.max(0,state.onboardingStep-1);render();return}
 if(el.dataset.obRole){state.onboardingRole=el.dataset.obRole;render();return}
 if(el.hasAttribute('data-ob-next')){const key=obSteps()[state.onboardingStep];if(key==='account'&&(!state.accountEmail.trim()||!state.accountPhone.trim()||state.accountPassword.length<6||!state.accountAccepted)){showToast('Completa tus datos y acepta los términos para continuar');return}if(key==='profile'&&!state.onboardingName.trim()){showToast('Escribe tu nombre para continuar');return}if(key==='business'&&!state.shopName.trim()){showToast('Escribe el nombre de tu negocio');return}state.onboardingStep=Math.min(obSteps().length-1,state.onboardingStep+1);render();return}
 if(el.hasAttribute('data-ob-skip')){state.wallet='';state.onboardingStep=Math.min(obSteps().length-1,state.onboardingStep+1);render();return}
 if(el.dataset.obPayment){state.paymentMethods[el.dataset.obPayment]=!state.paymentMethods[el.dataset.obPayment];render();return}
 if(el.dataset.obWallet){state.wallet=state.wallet===el.dataset.obWallet?'':el.dataset.obWallet;render();return}
 if(el.dataset.interest){state.interests=state.interests.includes(el.dataset.interest)?state.interests.filter(i=>i!==el.dataset.interest):[...state.interests,el.dataset.interest];render();return}
 if(el.hasAttribute('data-ob-complete')){state.onboardingStep=0;setPage(state.onboardingRole==='Quiero comprar'?'home':'merchant-dashboard');showToast('¡Tu perfil de BARRIO está listo!');return}
 if(el.dataset.shopFilter){state.shopFilter=el.dataset.shopFilter;render();return}
 if(el.dataset.productId){state.selectedProductId=Number(el.dataset.productId);state.detailQty=1;setPage('product-detail');return}
 if(el.dataset.detailQty){state.detailQty=Math.max(1,(state.detailQty||1)+(el.dataset.detailQty==='+'?1:-1));render();return}
 if(el.hasAttribute('data-add-cart')){const id=state.selectedProductId;const item=state.cart.find(x=>x.id===id);if(item)item.qty+=state.detailQty||1;else state.cart.push({id,qty:state.detailQty||1});setPage('cart');showToast('Producto agregado a tu carrito');return}
 if(el.dataset.cartQty){const [rawId,op]=el.dataset.cartQty.split(':');const item=state.cart.find(x=>x.id===Number(rawId));if(item){item.qty+=op==='+'?1:-1;if(item.qty<1)state.cart=state.cart.filter(x=>x!==item)}render();return}
 if(el.dataset.cartRemove){state.cart=state.cart.filter(x=>x.id!==Number(el.dataset.cartRemove));render();return}
 if(el.hasAttribute('data-clear-cart')){state.cart=[];render();return}
 if(el.dataset.delivery){state.delivery=el.dataset.delivery;render();return}
 if(el.dataset.checkoutPayment){state.payment=el.dataset.checkoutPayment;state.cryptoRiskMode='normal';state.cryptoVerificationPassed=false;render();return}
 if(el.dataset.cryptoRiskMode){state.cryptoRiskMode=el.dataset.cryptoRiskMode;state.cryptoVerificationPassed=false;render();return}
 if(el.hasAttribute('data-crypto-cancel')){state.cryptoVerificationPassed=false;setPage('checkout');showToast('Pago cancelado; no se envió ninguna solicitud a la billetera');return}
 if(el.hasAttribute('data-crypto-verify')){state.cryptoVerificationPassed=true;setPage('payment-processing');showToast('Verificación de demostración aprobada');return}
 if(el.hasAttribute('data-review-payment')){if(!state.cart.length){showToast('Tu carrito está vacío');setPage('shop-discover');return}if(state.delivery==='Entrega local'&&!state.deliveryAddress.trim()){showToast('Escribe la dirección para la entrega local');return}if(state.payment.startsWith('HBAR')&&state.cryptoRiskMode==='suspicious'){state.cryptoVerificationPassed=false;setPage('crypto-verification');return}setPage('payment-processing');return}
 if(el.hasAttribute('data-confirm-order')){if(state.payment.startsWith('HBAR')&&state.cryptoRiskMode==='suspicious'&&!state.cryptoVerificationPassed){setPage('crypto-verification');showToast('Completa la verificación antes de ir a tu billetera');return}const items=state.cart.map(l=>{const p=catalog().find(x=>x.id===l.id);return p?{id:p.id,name:p.name,emoji:p.emoji,price:p.price,qty:l.qty}:null}).filter(Boolean);const total=items.reduce((sum,x)=>sum+x.price*x.qty,0);const id=`BR-${state.orderNumber++}`;state.currentOrder={id,amount:total,items,status:'Nuevo',delivery:state.delivery,payment:state.payment};demoOrders.unshift({id,customer:'Ana Ramírez',items:`${items.length} artículos · $${total} MXN`,amount:total,status:'Nuevo',time:'Ahora',emoji:'🛍️'});state.cart=[];state.customerOrder='';state.cryptoVerificationPassed=false;state.cryptoRiskMode='normal';setPage('order-confirmation');showToast('Pago simulado correctamente');return}
 if(el.dataset.orderId){state.selectedOrder=el.dataset.orderId;setPage('merchant-order-detail');return}
 if(el.dataset.customerOrder){state.customerOrder=el.dataset.customerOrder;setPage('customer-order-detail');return}
 if(el.dataset.orderFilter){state.merchantOrderFilter=el.dataset.orderFilter;render();return}
 if(el.dataset.merchantFilter){state.merchantFilter=el.dataset.merchantFilter;render();return}
 if(el.hasAttribute('data-new-product')){state.editingProductId=null;state.merchantForm={name:'',price:'',category:'Bebidas',description:'',stock:''};setPage('merchant-product-form');return}
 if(el.dataset.editProduct){state.editingProductId=Number(el.dataset.editProduct);const product=state.merchantProducts.find(x=>x.id===state.editingProductId);state.merchantForm=product?{...product,description:product.description||''}:{name:'',price:'',category:'Bebidas',description:'',stock:''};setPage('merchant-product-form');return}
 if(el.hasAttribute('data-save-product')){const f=state.merchantForm;if(!f.name.trim()||Number(f.price)<=0){showToast('Agrega el nombre y un precio válido');return}if(state.editingProductId){const p=state.merchantProducts.find(x=>x.id===state.editingProductId);Object.assign(p,{name:f.name.trim(),price:Number(f.price),category:f.category,description:f.description,stock:Number(f.stock||p.stock),status:Number(f.stock||p.stock)<10?'Stock bajo':'En existencia'})}else state.merchantProducts.unshift({id:Math.max(0,...state.merchantProducts.map(p=>p.id))+1,name:f.name.trim(),price:Number(f.price),category:f.category,description:f.description,stock:Number(f.stock||0),emoji:'🧁',status:Number(f.stock||0)<10?'Stock bajo':'En existencia'});state.editingProductId=null;setPage('merchant-products');showToast('Producto guardado en esta sesión');return}
 if(el.hasAttribute('data-advance-order')){const order=demoOrders.find(x=>x.id===state.selectedOrder);if(order){if(order.status==='Nuevo')order.status='Preparando';else if(order.status==='Preparando')order.status='Listo';else if(order.status==='Listo')order.status='Completado';render();showToast('Pedido actualizado: '+order.status)}return}
});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-ob-field]')){const field=el.dataset.obField;const map={shopZone:'onboardingZone',shopName:'shopName',shopKind:'shopKind',name:'onboardingName',bio:'onboardingBio',shopBio:'shopBio',accountEmail:'accountEmail',accountPhone:'accountPhone',accountPassword:'accountPassword'};state[map[field]||field]=el.value}if(el.matches('[data-account-terms]'))state.accountAccepted=el.checked;if(el.matches('[data-delivery-address]'))state.deliveryAddress=el.value;if(el.matches('[data-product-field]'))state.merchantForm[el.dataset.productField]=el.value;if(el.matches('[data-action="shop-search-change"]')){state.shopQuery=el.value;const pos=el.selectionStart;render();const next=app.querySelector('[data-action="shop-search-change"]');next?.focus();next?.setSelectionRange(pos,pos)}if(el.matches('[data-action="merchant-product-search"]')){state.merchantSearch=el.value;const pos=el.selectionStart;render();const next=app.querySelector('[data-action="merchant-product-search"]');next?.focus();next?.setSelectionRange(pos,pos)}if(el.matches('[data-action="merchant-order-search"]')){state.orderSearch=el.value;const pos=el.selectionStart;render();const next=app.querySelector('[data-action="merchant-order-search"]');next?.focus();next?.setSelectionRange(pos,pos)}if(el.matches('[data-action="merchant-customer-search"]')){state.customerSearch=el.value;const pos=el.selectionStart;render();const next=app.querySelector('[data-action="merchant-customer-search"]');next?.focus();next?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-ob-field]')){const field=el.dataset.obField;if(field==='shopZone')state.onboardingZone=el.value;else if(field==='shopKind')state.shopKind=el.value}if(el.matches('[data-account-terms]'))state.accountAccepted=el.checked;if(el.matches('[data-product-field]'))state.merchantForm[el.dataset.productField]=el.value});
document.addEventListener('click',e=>{const item=e.target.closest('.nav-item');if(item){if(item.dataset.ownerPage)setPage(item.dataset.ownerPage);else if(item.dataset.page)setPage(item.dataset.page)}});
render();
